-  async function run() {
+  // ── live, forgiving evaluation ──────────────────────────────────────────────
+  // Compile (and run) the buffer as the user types, debounced. The Rian parser is
+  // not error-recovering, so a half-typed line throws — so we (1) stay quiet for
+  // input that is *obviously* mid-edit (unbalanced delimiters/strings, an unclosed
+  // `do`, a dangling operator), and (2) on any compile error keep the LAST GOOD
+  // panes and report it gently instead of flashing red. A generation token drops
+  // stale results when a newer keystroke supersedes an in-flight compile/run.
+  let liveTimer = 0;
+  let evalGen = 0;
+
+  // A cheap "is the buffer obviously incomplete?" check — NOT a parser, just enough
+  // to avoid yelling at code the user is still in the middle of writing.
+  function looksIncomplete(srcText: string): boolean {
+    const code = srcText.replace(/#[^\n]*/g, " "); // drop line comments
+    if (code.trim() === "") return true;
+    // single walk: balance delimiters AND collapse each string literal to a `0`
+    // placeholder, so the `do`/`end` and trailing-operator checks below see only
+    // real code (a string like "do" or a trailing "text" must not mislead them).
+    let inStr = false,
+      q = "",
+      par = 0,
+      brk = 0,
+      brc = 0,
+      bare = "";
+    for (let i = 0; i < code.length; i++) {
+      const c = code[i];
+      if (inStr) {
+        if (c === q && code[i - 1] !== "\\") inStr = false;
+        continue; // string contents contribute nothing to `bare`
+      }
+      if (c === '"' || c === "'") (inStr = true), (q = c), (bare += "0");
+      else {
+        if (c === "(") par++;
+        else if (c === ")") par--;
+        else if (c === "[") brk++;
+        else if (c === "]") brk--;
+        else if (c === "{") brc++;
+        else if (c === "}") brc--;
+        bare += c;
+      }
+    }
+    if (inStr || par > 0 || brk > 0 || brc > 0) return true; // unterminated string / open delimiter
+    const doN = (bare.match(/\bdo\b/g) || []).length;
+    const endN = (bare.match(/\bend\b/g) || []).length;
+    if (doN > endN) return true; // an unclosed `do` block
+    // a buffer ending on an operator/keyword is mid-expression
+    return /(:=|<~|<-|->|\|>|<>|[-+*\/<>=.,]|\b(?:and|or|not|when|do|else|div|rem|in)\b)\s*$/.test(bare.trim());
+  }
